where th.slug = 'kerketta-auditorium' on conflict do nothing;

-- Shows for the next 14 days from each theatre's weekly schedule
insert into shows (movie_id, theatre_id, screen_id, show_date, show_time, price_offrs, price_jcos, price_ors)
select m.id, th.id, sc.id, d::date, slot.value::time, 150, 100, 70
from theatres th join screens sc on sc.theatre_id = th.id
cross join generate_series(current_date, current_date + 13, interval '1 day') d
cross join lateral jsonb_array_elements_text(th.weekly_schedule -> extract(dow from d)::int::text) with ordinality as slot(value, idx)
join movies m on m.slug = (array['mirzapur']::text[])[1 + ((extract(doy from d)::int + slot.idx::int) % 1)]
where th.slug = 'kerketta-auditorium' on conflict do nothing;

commit;

